#pragma HLS ARRAY_PARTITION variable = x_buffer type = cyclic factor =         \
    GS dim = 1

  static float xs_buffer[N / GS];
#pragma HLS ARRAY_PARTITION variable = xs_buffer type = cyclic factor =        \
    GS dim = 1

