  for (int i = 0; i < N; i++) {
#pragma HLS pipeline II = 1
    x_buffer[i] = xq[i];
  }
xs_buff:
  for (int j = 0; j <= N - GS; j += GS) {
#pragma HLS pipeline II = 1
    xs_buffer[j / GS] = xs[j / GS];
  }

matmul1:
  for (int i = 0; i < D; i++) {
    const int w_row_offset = i * N;
    const int ws_row_offset = i * (N / GS);

    xout[i] = 0.0f;

