		for (j = 0; j < SAMPLE_SZ; j++) {
			inBuf[j] = i + j - (sz >> 1);
		}

		fix_fftr(FFT_SAMP, 0);

		if(INVERSE == 1)
			fix_fftr(FFT_SAMP, 1);

		i += SAMPLE_SZ;
	}

	return 0;
}

