template<int OUTPUT_DIM>
void activation_softmax(TYPE_T in[OUTPUT_DIM])
{
	/* find the maximum */
	TYPE_T max = in[0];
	for(int i = 1; i < OUTPUT_DIM; i++)
	{
#pragma HLS pipeline
		if( in[i] > max)
			max = in[i];
	}

	/* calculate the new value */
	TYPE_T val[OUTPUT_DIM];
	TYPE_T sum = 0;
	for( int i = 0; i < OUTPUT_DIM; i++)
	{
#pragma HLS pipeline
		val[i] = expf(in[i] - max);
		sum += val[i];
	}

	/* calculate the result */
	for( int i = 0; i < OUTPUT_DIM; i++)
	{
#pragma HLS pipeline
		in[i] = val[i]/sum;
	}

}


